# Write your MySQL query statement below
select distinct p.product_id, p.product_name from product p left join sales s on p.product_id = s.product_id where s.sale_date between '2019-01-01' and '2019-03-31' and p.product_id not in (select p1.product_id from product p1 left join sales s1 on p1.product_id = s1.product_id where s1.sale_date not between '2019-01-01' and '2019-03-31');